func() -> void:
		var axis_label := "V"
		var plotted_series: Array[Dictionary] = []
		if mode_selector.selected == 0:
			axis_label = "V"
			var selected_net_indices := range(net_data_by_index.size())
			if not compare_check.button_pressed and not net_data_by_index.is_empty():
				selected_net_indices = [net_selector.selected]
			for net_index in selected_net_indices:
				var selected_net: Dictionary = net_data_by_index[net_index]
				var values: Array[float] = []
				var node_id: int = selected_net["solver_node_id"]
				for sample in result.transient_node_voltages:
					if sample.has(node_id):
						values.append(sample[node_id])
				plotted_series.append({
					"name": selected_net["name"],
					"values": values
				})
		else:
			axis_label = "A"
			var selected_component_indices := range(component_names.size())
			if not compare_check.button_pressed and not component_names.is_empty():
				selected_component_indices = [component_selector.selected]
			for component_index in selected_component_indices:
				var component_name: String = component_names[component_index]
				plotted_series.append({
					"name": component_name,
					"values": result.transient_component_currents[
						component_name
					].duplicate()
				})
		plot.set_ylabel(axis_label)
		plot.set_data(result.time_points, plotted_series)

